/** Read-only source map for the assistant, generated by scripts/assistant/build_code_index.mjs before each build. Server-only. */
import index from "./codeIndex.server.json";

export type CodeEntry = {
  path: string;
  kind: string;
  route?: string;
  lines: number;
  summary: string;
  exports: string[];
  serverFns?: string[];
  datasets?: string[];
  components?: string[];
};

const files = (index as { files: CodeEntry[] }).files;

/** Files ranked by how many query words appear in their path, route, summary, exports and datasets. */
export function searchCode(query: string, limit = 12): CodeEntry[] {
  const words = query
    .toLowerCase()
    .split(/[^a-z0-9_$/.-]+/)
    .filter((w) => w.length > 1);
  if (!words.length) return [];
  return files
    .map((f) => {
      const hay = [
        f.path,
        f.route ?? "",
        f.summary,
        ...f.exports,
        ...(f.datasets ?? []),
        ...(f.serverFns ?? []),
      ]
        .join(" ")
        .toLowerCase();
      const score = words.reduce(
        (s, w) =>
          s +
          (hay.includes(w) ? 1 : 0) +
          (f.path.toLowerCase().includes(w) ? 1 : 0) +
          (f.route?.toLowerCase().includes(w) ? 2 : 0),
        0,
      );
      return { f, score };
    })
    .filter((x) => x.score > 0)
    .sort((a, b) => b.score - a.score || a.f.path.localeCompare(b.f.path))
    .slice(0, limit)
    .map((x) => x.f);
}

export function codeFile(path: string): CodeEntry | null {
  return files.find((f) => f.path === path) ?? null;
}

/** The route file whose path pattern matches a URL path ("/courts/cand" → "/courts/$id"). */
export function routeForPath(pathname: string): CodeEntry | null {
  const clean = pathname.split(/[?#]/)[0]!.replace(/\/+$/, "") || "/";
  const routes = files.filter((f) => f.route);
  const toRegex = (route: string) =>
    new RegExp(
      "^" +
        route
          .replace(/\/$/, "")
          .split("/")
          .map((seg) =>
            seg.startsWith("$")
              ? "[^/]+"
              : seg.replace(/_$/, "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&"),
          )
          .join("/") +
        "/?$",
    );
  const params = (r: CodeEntry) => r.route!.split("$").length - 1;
  // Static segments win over parameters ("/courts/firms" before "/courts/$id").
  return (
    routes
      .filter((r) => toRegex(r.route!).test(clean))
      .sort((a, b) => params(a) - params(b) || b.route!.length - a.route!.length)[0] ?? null
  );
}
